function findPeakElement(nums: number[]): number {
  // Пик всегда есть на отрезке [lo, hi]: за его границами
  // значения «спускаются» (по условию nums[-1] = nums[n] = -∞)
  let lo = 0;
  let hi = nums.length - 1;

  while (lo < hi) {
    const mid = lo + ((hi - lo) >> 1);

    if (nums[mid] < nums[mid + 1]) {
      // Идём в гору: справа от mid обязательно есть пик
      lo = mid + 1;
    } else {
      // Спускаемся (nums[mid] > nums[mid + 1]):
      // пик — сам mid или левее
      hi = mid;
    }
  }

  // Отрезок сжался до одной точки — это пик
  return lo;
}

// Время: O(log n)
// Память: O(1)
